  /// Read this payload from a decoded JSON object.
  factory Payload.fromJson(Map<String, dynamic> json) => Payload(
        did: json['did'] as String,
        document: json['document'] as Map<String, dynamic>?,
        methodParameters: json['methodParameters'] as Map<String, dynamic>?,
        label: json['label'] as String?,
        expectedVersionId: json['expectedVersionId'] as String?,
        dryRun: json['dryRun'] as bool?,
        previewId: json['previewId'] as String?,
        reason: json['reason'] as String?,
        ext: json['ext'] as Map<String, dynamic>?,
      );

  /// The key-role identity, by DID (for a `did:scid` identity, the DID without `src`).
  final String did;

  /// The new identifier document, for methods whose controller writes it. Omit to leave
  /// it unchanged. It MUST carry, unchanged, `verificationMethod`, every verification
  /// relationship and `keyRoles`: a change to any of them is refused with
  /// `vta/dids/update:keyMembersManaged`, because keys change only through the key-role
  /// tasks.
  final Map<String, dynamic>? document;

  /// Validated against the method profile's `UpdateParameters` schema
  /// (method-profiles/&lt;method&gt;.schema.json); a member it does not define, or one fixed
  /// at creation, is refused with `vta/dids:methodParameterUnsupported`.
  final Map<String, dynamic>? methodParameters;

  /// Operator-facing audit label.
  final String? label;

  /// Optimistic-concurrency precondition: the version identifier (method profile §3) the
  /// caller based this change on, for example `keys/list`'s `versionId`. The VTA MUST
  /// refuse with `vta/dids:versionConflict` if the identity has moved past it. Not
  /// optional for anything a person looked at.
  final String? expectedVersionId;

  /// Compute and return the preview without writing anything but the plan
  /// (CONVENTIONS.md §6.1). Absent reads as false.
  final bool? dryRun;

  /// Apply exactly the plan a previous dry run of this same request returned, or nothing
  /// (CONVENTIONS.md §6.1); what every approval is bound to.
  final String? previewId;

  /// Why the change is being made, for the audit trail and for the other approvers.
  /// Never published.
  final String? reason;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'did': did,
        if (document != null) 'document': document!,
        if (methodParameters != null) 'methodParameters': methodParameters!,
        if (label != null) 'label': label!,
        if (expectedVersionId != null) 'expectedVersionId': expectedVersionId!,
        if (dryRun != null) 'dryRun': dryRun!,
        if (previewId != null) 'previewId': previewId!,
        if (reason != null) 'reason': reason!,
        if (ext != null) 'ext': ext!,
      };
}

